package dev.pathland.view.core

import dev.pathland.view.core.signal.Signal
import dev.pathland.view.core.signal.Signals
import dev.pathland.view.core.state.PersistentState

/**
 * The rendering environment — the single inheritance/scoping mechanism.
 *
 * It carries the session's `PersistentState` and the root-declared window
 * metadata. Inheritable values live in a separate thread-local scope stack
 * (`Environment.current()`); `within`/`restore` bracket each render.
 */
class Environment(private val state: PersistentState?) {

    private var windowMetadata: WindowMetadata? = null

    /** The window/surface metadata declared by the root, or null. */
    fun windowMetadata(): WindowMetadata? = windowMetadata

    /** Record the root-declared window metadata during its render. */
    internal fun setWindowMetadata(metadata: WindowMetadata?) {
        windowMetadata = metadata
    }

    /** The session's persistent state (null for a stateless environment). */
    fun state(): PersistentState? = state

    companion object {
        @JvmField
        val BUTTON_STYLE: EnvironmentKey<ButtonStyle> = EnvironmentKey.of("buttonStyle")

        @JvmField
        val LABEL_STYLE: EnvironmentKey<LabelStyle> = EnvironmentKey.of("labelStyle")

        @JvmField
        val VIDEO_STYLE: EnvironmentKey<VideoStyle> = EnvironmentKey.of("videoStyle")

        private val VALUES: ThreadLocal<EnvironmentValues> =
            ThreadLocal.withInitial { EnvironmentValues.empty() }

        /** The default environment (no persistent state). */
        @JvmField
        val DEFAULT = Environment(null)

        /** The current scope (empty at the top of a render). */
        fun current(): EnvironmentValues = VALUES.get()

        /** The scoped value for [key] as a signal (reactive). */
        @JvmStatic
        fun <T> value(key: EnvironmentKey<T>): Signal<T> {
            val scope = VALUES.get()
            if (scope.contains(key)) {
                return toSignal(scope.get(key))
            }
            return EnvironmentSignal(key)
        }

        @Suppress("UNCHECKED_CAST")
        private fun <T> toSignal(value: Any?): Signal<T> {
            if (value is Signal<*>) return value as Signal<T>
            return Signal { value as T }
        }

        /** A lazy environment signal: it captures the value at read time when the key is in scope. */
        private class EnvironmentSignal<T>(private val key: EnvironmentKey<T>) : Signal<T> {
            private var captured: Signal<T>? = null

            @Suppress("UNCHECKED_CAST")
            override fun get(): T {
                val scope = VALUES.get()
                if (scope.contains(key)) {
                    captured = toSignal(scope.get(key))
                }
                return captured?.get() as T
            }
        }

        /** Temporarily set the active scope for a render. */
        fun within(scope: EnvironmentValues) {
            VALUES.set(scope)
        }

        /** Restore the previous active scope. */
        fun restore(previous: EnvironmentValues) {
            VALUES.set(previous)
        }
    }
}
package dev.pathland.view.dsl

import dev.pathland.view.core.ButtonStyle
import dev.pathland.view.core.EmptyContent
import dev.pathland.view.core.Environment
import dev.pathland.view.core.View
import dev.pathland.core.protocol.Commands
import dev.pathland.core.protocol.Components
import dev.pathland.core.protocol.Properties
import dev.pathland.view.core.signal.Signal
import dev.pathland.view.engine.PathlandNode

internal fun buttonView(
    title: Signal<String>?,
    action: (() -> Unit)?,
    children: List<View>,
): View = coreView(Components.BUTTON) { node, env ->
    val label = children.firstOrNull() ?: title?.let { textView(it) }
    val style = Environment.value(Environment.BUTTON_STYLE).get() ?: PlainButtonStyle
    val content = style.makeBody(ButtonStyle.Configuration(label))
    if (content != null && content !== EmptyContent.INSTANCE) {
        node.children.add(content.render(env))
    }
    val mask = (node.properties[Properties.EVENT_LISTENERS] as? Int ?: 0) or
        Commands.Listeners.POINTER_DOWN or Commands.Listeners.POINTER_UP
    node.properties[Properties.EVENT_LISTENERS] = mask
    if (action != null) node.tapActions.add(Runnable(action))
}

/** A button with a plain-text title. */
fun Button(title: String, action: () -> Unit): View =
    buttonView(dev.pathland.view.core.signal.Signals.constant(title), action, emptyList()).registerChild()

/** A button whose title is bound to a signal. */
fun Button(title: Signal<String>, action: () -> Unit): View =
    buttonView(title, action, emptyList()).registerChild()

/**
 * A button with a custom label: `Button(action = { save() }) { Text("Save") }`.
 * The action is a named argument because the trailing lambda is the label.
 */
fun Button(action: () -> Unit, content: PathlandScope.() -> Unit): View {
    val children = collectChildren(content)
    return buttonView(null, action, children).registerChild()
}

/** A button with both a title and an explicit label subtree (the subtree wins). */
fun Button(title: String, action: () -> Unit, content: PathlandScope.() -> Unit): View {
    val children = collectChildren(content)
    return buttonView(dev.pathland.view.core.signal.Signals.constant(title), action, children).registerChild()
}

