fun NavigationLink(
    to: String,
    router: Router? = null,
    content: PathlandScope.() -> Unit,
): View {
    val children = collectChildren(content)
    val label = when (children.size) {
        0 -> textView("")
        1 -> children[0]
        else -> groupView(children)
    }
