/** One static navigation section in the left sidebar. */
private data class NavigationItem(val label: String, val icon: IconName)

/**
 * The Apple Music-style left navigation sidebar: a compact, static section list
 * (Library/Playlists/Artists/Albums/Songs) using the DSL `List` with
 * `SidebarListStyle`. Selection is local visual feedback only; navigation and
 * filtering are future work.
 */
internal class NavigationSidebar : Component() {

    private val items = listOf(
        NavigationItem("Library", IconName.FOLDER),
        NavigationItem("Playlists", IconName.LIST),
        NavigationItem("Artists", IconName.USERS),
        NavigationItem("Albums", IconName.GRID),
        NavigationItem("Songs", IconName.MUSIC),
    )

    override fun body(): View {
        val service = mediaPlayerService()
        val selection = LazySelection(service.navIndex, service.navFocused)

        return VStack(alignment = HorizontalAlignment.LEADING, spacing = 12f) {
            Text("Music")
                .font(Font.largeTitle())
                .fontSize(22f)
                .fontWeight(FontWeight.BOLD)

            PathlandList(selection = selection) {
                items.forEach { item -> NavigationRow(item) }
            }.listStyle(SidebarListStyle)
        }
            .padding(16f)
            .background(CoreColor.token("list.sidebar.background"))
            .foregroundStyle(CoreColor.token("list.sidebar.foreground"))
            .accessibilityRole(Roles.NAVIGATION)
            .frame(
                width = MusicPlayerView.NAV_SIDEBAR_WIDTH,
                height = Commands.Size.FILL,
            )
    }

    private fun NavigationRow(item: NavigationItem): View =
        HStack(alignment = VerticalAlignment.CENTER, spacing = 10f) {
            Icon(item.icon)
                .fontSize(16f)
                .frame(width = 18f, height = 18f)
            Text(item.label)
                .fontSize(14f)
                .fontWeight(FontWeight.SEMIBOLD)
            Spacer()
        }
}
package dev.pathland.demo;

import dev.pathland.view.core.AdaptiveTheme;
import dev.pathland.view.core.Theme;

/**
 * The demo's theme: a **light** {@link Theme} and a **dark** {@link Theme},
 * composed via {@link AdaptiveTheme} (spec/TOKENS.md). The renderer resolves
 * each token against the platform's color scheme, so the HTML/JS DOM demo
 * re-themes under {@code prefers-color-scheme: dark} and a native GTK renderer
 * under its dark variant — with no re-emission.
 */
public final class DemoTheme {

    /** Light (base) values. */
    private static final Theme LIGHT = new Theme()
            .color("color.primary", 0xFF2563EB)
            .color("color.surface", 0xFFFFFFFF)
            .color("color.accent", 0xFF2563EB)
            .f32("space.base", 4.0f)
            .color("control.background", 0xFFF9FAFB)
            .color("control.foreground", 0xFF111827)
            .color("control.accent", 0xFF2563EB)
            .color("list.sidebar.background", 0xFFF6F7FA);

    /** Dark values (emitted with the {@code dark.} scheme prefix). */
    private static final Theme DARK = new Theme()
            .color("color.primary", 0xFF60A5FA)
            .color("color.surface", 0xFF111827)
            .color("color.accent", 0xFF60A5FA)
            .color("control.background", 0xFF1F2937)
            .color("control.foreground", 0xFFF9FAFB)
            .color("control.accent", 0xFF60A5FA)
            .color("list.sidebar.background", 0xFF1F2937);

    private DemoTheme() {}

    /** The light (base) theme. */
    public static Theme light() {
        return LIGHT;
    }

    /** The dark theme. */
    public static Theme dark() {
        return DARK;
    }

    /** The demo's adaptive theme (per-app, global overrides; safe to share across sessions). */
    public static AdaptiveTheme adaptive() {
        return new AdaptiveTheme(LIGHT, DARK);
    }
}

